import { 
  getUserFavorites, 
  addFavorite, 
  removeFavorite, 
  isBookFavorite 
} from '../services/favorite.service';
import { FileSystemError, NotFoundError } from '../utils/errors';
import { BookModel } from '../models/book';

/**
 * Controller for favorites-related endpoints
 */
export class FavoriteController {
  /**
   * Get all favorite books for a user
   * @param req Express request object
   * @param res Express response object
   */
  static async getUserFavorites(req: Request, res: Response) {
    try {
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          status: 'error',
          error: { code: 401, message: 'Authentication required' },
          data: null
        });
      }

      // Get favorite book IDs
      const favoriteIds = await getUserFavorites(userId);

      if (favoriteIds.length === 0) {
        return res.status(200).json({
          status: 'success',
          data: [],
          error: null
        });
      }

      // Get book details for each favorite
      const favoriteBooks = await Promise.all(
        favoriteIds.map(async (bookId) => {
          try {
            const book = await BookModel.getBookById(bookId);
            return book;
          } catch (error) {
            console.error(`Error fetching book ${bookId}:`, error);
            return null;
          }
        })
      );

      // Filter out any null books (in case some weren't found)
      const validBooks = favoriteBooks.filter(Boolean);

      return res.status(200).json({
        status: 'success',
        data: validBooks,
        error: null
      });
    } catch (error) {
      console.error('Error in getUserFavorites controller:', error);
      return res.status(500).json({
        status: 'error',
        error: { code: 500, message: 'Failed to retrieve favorite books' },
        data: null
      });
    }
  }

  /**
   * Check if a book is in user's favorites
   * @param req Express request object
   * @param res Express response object
   */
  static async checkFavorite(req: Request, res: Response) {
    try {
      const userId = req.user?.id;
      const { bookId } = req.params;

      if (!userId) {
        return res.status(401).json({
          status: 'error',
          error: { code: 401, message: 'Authentication required' },
          data: null
        });
      }

      const isFavorite = await isBookFavorite(userId, bookId);

      return res.status(200).json({
        status: 'success',
        data: { isFavorite },
        error: null
      });
    } catch (error) {
      console.error('Error in checkFavorite controller:', error);
      return res.status(500).json({
        status: 'error',
        error: { code: 500, message: 'Failed to check favorite status' },
        data: null
      });
    }
  }

  /**
   * Add a book to user's favorites
   * @param req Express request object
   * @param res Express response object
   */
  static async addFavorite(req: Request, res: Response) {
    try {
      const userId = req.user?.id;
      const { bookId } = req.params;

      if (!userId) {
        return res.status(401).json({
          status: 'error',
          error: { code: 401, message: 'Authentication required' },
          data: null
        });
      }

      // Verify book exists
      const book = await BookModel.getBookById(bookId);
      if (!book) {
        return res.status(404).json({
          status: 'error',
          error: { code: 404, message: 'Book not found' },
          data: null
        });
      }

      // Add to favorites
      const favorites = await addFavorite(userId, bookId);

      return res.status(200).json({
        status: 'success',
        data: { isFavorite: true, favorites },
        error: null
      });
    } catch (error) {
      console.error('Error in addFavorite controller:', error);
      return res.status(500).json({
        status: 'error',
        error: { code: 500, message: 'Failed to add book to favorites' },
        data: null
      });
    }
  }

  /**
   * Remove a book from user's favorites
   * @param req Express request object
   * @param res Express response object
   */
  static async removeFavorite(req: Request, res: Response) {
    try {
      const userId = req.user?.id;
      const { bookId } = req.params;

      if (!userId) {
        return res.status(401).json({
          status: 'error',
          error: { code: 401, message: 'Authentication required' },
          data: null
        });
      }

      // Remove from favorites
      const favorites = await removeFavorite(userId, bookId);

      return res.status(200).json({
        status: 'success',
        data: { isFavorite: false, favorites },
        error: null
      });
    } catch (error) {
      console.error('Error in removeFavorite controller:', error);
      return res.status(500).json({
        status: 'error',
        error: { code: 500, message: 'Failed to remove book from favorites' },
        data: null
      });
    }
  }
